module tb;

  // -----------------------------------------------------------------
  // Clock and reset
  // -----------------------------------------------------------------
  localparam int CLK_PERIOD = 10; // 100 MHz
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  logic rst = 1;

  // -----------------------------------------------------------------
  // DUT ports
  // -----------------------------------------------------------------
  logic [7:0]  s_axis_tdata;
  logic        s_axis_tvalid;
  logic        s_axis_tready; // observed, not driven
  logic        txd;
  logic        busy;
  logic [15:0] prescale = 16'd5; // non‑zero, kept stable

  // -----------------------------------------------------------------
  // Instantiate the transmitter (default DATA_WIDTH = 8)
  // -----------------------------------------------------------------
  uart_tx #(.DATA_WIDTH(8)) dut (
    .clk        (clk),
    .rst        (rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .txd        (txd),
    .busy       (busy),
    .prescale   (prescale)
  );

  // -----------------------------------------------------------------
  // Testbench stimulus
  // -----------------------------------------------------------------
  initial begin
    // 1. Assert reset
    #(CLK_PERIOD*2);
    rst = 0;   // release reset

    // 2. First load – present a byte while tready is still low
    s_axis_tdata  = 8'hA5;
    s_axis_tvalid = 1'b1;

    // wait until the DUT raises tready (handshake completes)
    @(posedge clk);
    wait (s_axis_tready == 1'b1);
    s_axis_tvalid = 1'b0;   // de‑assert tvalid

    // 3. Wait for the transmitter to become idle again
    repeat (200) @(posedge clk); // enough time for one frame to shift out

    // 4. Second load – present the next byte (8'h3C) while idle
    s_axis_tdata  = 8'h3C;
    s_axis_tvalid = 1'b1;
    @(posedge clk);
    s_axis_tvalid = 1'b0;

    // 5. Let the design finish shifting; then end simulation
    repeat (500) @(posedge clk);
    $finish;
  end

  // -----------------------------------------------------------------
  // Clock generation
  // -----------------------------------------------------------------
  initial begin
    #(CLK_PERIOD/2);
    forever #(CLK_PERIOD/2) clk = ~clk;
  end

endmodule
